  trapTitle: { en: (a, b) => `Why so bumpy between ${a} and ${b}?`, nl: (a, b) => `Waarom zo grillig tussen ${a} en ${b}?`, fr: (a, b) => `Pourquoi si heurté entre ${a} et ${b} ?` },
  trapBody: {
    en: (a, b, s15, s20, ex) => `Low pay gets three payslip bonuses, and each ends with a jump. From ${a} the 1 200 € trattamento integrativo starts, and it stops all at once at ${s15}, where the tax-free cuneo bonus also drops from 5.3% to 4.8% of income. At ${s20} the cuneo bonus ends and a 1 000 € tax deduction takes over, which then fades out until ${b}: every extra euro there also costs 12.5 cents of deduction.${ex ? ` Your comune exempts incomes up to ${ex}; one euro more and the surcharge is due on all of it.` : ''}`,
    nl: (a, b, s15, s20, ex) => `Lage lonen krijgen drie premies op de loonstrook, en elk eindigt met een sprong. Vanaf ${a} begint de trattamento integrativo van 1 200 €, die in één keer stopt bij ${s15}, waar ook de belastingvrije cuneo-premie zakt van 5,3% naar 4,8% van het inkomen. Bij ${s20} stopt de cuneo-premie en neemt een belastingaftrek van 1 000 € het over, die afbouwt tot ${b}: elke extra euro kost daar ook 12,5 cent aftrek.${ex ? ` Jouw comune stelt inkomens tot ${ex} vrij; één euro meer en de opcentiemen gelden op alles.` : ''}`,
    fr: (a, b, s15, s20, ex) => `Les bas salaires reçoivent trois primes sur la fiche de paie, et chacune finit par un saut. Dès ${a} commence le trattamento integrativo de 1 200 €, qui s'arrête d'un coup à ${s15}, où la prime cuneo exonérée passe aussi de 5,3% à 4,8% du revenu. À ${s20} la prime cuneo s'arrête et une déduction d'impôt de 1 000 € prend le relais, qui s'éteint jusqu'à ${b} : chaque euro de plus y coûte aussi 12,5 centimes de déduction.${ex ? ` Votre comune exonère les revenus jusqu'à ${ex} ; un euro de plus et l'additionnelle porte sur tout.` : ''}`,
  },
  topTitle: {
    en: (top, cap) => `Why the step at ${top}, and the drop at ${cap}?`,
    nl: (top, cap) => `Waarom de sprong bij ${top}, en de daling bij ${cap}?`,
    fr: (top, cap) => `Pourquoi la marche à ${top}, et la baisse à ${cap} ?`,
  },
  topBody: {
    en: (top, cap, br) => `From ${top} your taxable income passes ${br}: IRPEF jumps from 33% to 43%, and the employee deduction is already gone. A little higher, INPS adds 1% above 56 224 €. From ${cap} pension contributions stop at the INPS ceiling (for anyone first insured after 1995), so the rate on each extra euro falls.`,
    nl: (top, cap, br) => `Vanaf ${top} komt je belastbaar inkomen boven ${br}: de IRPEF springt van 33% naar 43%, en de werknemersaftrek is al weg. Iets hoger telt INPS 1% extra boven 56 224 €. Vanaf ${cap} stoppen de pensioenbijdragen aan het INPS-plafond (voor wie na 1995 voor het eerst verzekerd was), dus het tarief op elke extra euro daalt.`,
    fr: (top, cap, br) => `À partir de ${top}, votre revenu imposable dépasse ${br} : l'IRPEF passe de 33% à 43%, et la déduction des salariés a déjà disparu. Un peu plus haut, l'INPS ajoute 1% au-delà de 56 224 €. À partir de ${cap}, les cotisations retraite s'arrêtent au plafond INPS (pour les assurés depuis 1996), donc le taux sur chaque euro supplémentaire baisse.`,
  },

  // Tax components
  'comp.er': { en: `Employer contributions (INPS, INAIL)`, nl: `Werkgeversbijdragen (INPS, INAIL)`, fr: `Cotisations patronales (INPS, INAIL)` },
  'comp.ee': { en: `Employee contributions`, nl: `Werknemersbijdragen`, fr: `Cotisations salariales` },
