  'comp.com': { en: `Municipal surcharge`, nl: `Gemeentelijke opcentiemen`, fr: `Additionnelle communale` },
  'comp.bonus': { en: `Payslip bonuses (cuneo, integrativo)`, nl: `Premies op de loonstrook (cuneo, integrativo)`, fr: `Primes sur la fiche de paie (cuneo, integrativo)` },
  bonusReceived: { en: `+ Payslip bonuses for low pay`, nl: `+ Premies op de loonstrook voor lage lonen`, fr: `+ Primes sur la fiche de paie pour bas salaires` },
