  'er.naspi': { en: `Unemployment (NASpI)`, nl: `Werkloosheid (NASpI)`, fr: `Chômage (NASpI)` },
  'er.cuaf': { en: `Family benefits (CUAF)`, nl: `Gezinsbijslagen (CUAF)`, fr: `Prestations familiales (CUAF)` },
  'er.mat': { en: `Maternity`, nl: `Moederschap`, fr: `Maternité` },
  'er.tfrFund': { en: `Severance guarantee fund`, nl: `Waarborgfonds ontslagvergoeding`, fr: `Fonds de garantie du TFR` },
  'er.cigo': { en: `Short-time work (CIGO)`, nl: `Tijdelijke werkloosheid (CIGO)`, fr: `Chômage partiel (CIGO)` },
  'er.cigs': { en: `Extraordinary short-time work (CIGS)`, nl: `Buitengewone tijdelijke werkloosheid (CIGS)`, fr: `Chômage partiel extraordinaire (CIGS)` },
  'er.inail': { en: `Work accidents (INAIL, office)`, nl: `Arbeidsongevallen (INAIL, kantoor)`, fr: `Accidents du travail (INAIL, bureau)` },
  'bd.taxable': { en: `Taxable income`, nl: `Belastbaar inkomen`, fr: `Revenu imposable` },
  'bd.detLav': { en: `Employee deduction`, nl: `Aftrek voor werknemers`, fr: `Déduction des salariés` },
  'bd.detCon': { en: `Dependent spouse deduction`, nl: `Aftrek voor partner ten laste`, fr: `Déduction pour conjoint à charge` },
  'bd.detCun': { en: `Cuneo deduction (20 000 to 40 000 €)`, nl: `Cuneo-aftrek (20 000 tot 40 000 €)`, fr: `Déduction cuneo (20 000 à 40 000 €)` },
  'bd.somma': { en: `Tax-free cuneo bonus`, nl: `Belastingvrije cuneo-premie`, fr: `Prime cuneo exonérée` },
